  const big = (ctx, s, x, y, t, t0, o = {}) => MG.text.reveal(ctx, s, x, y, t, t0, { font: F.cond, weight: 900, size: o.size || 260, color: o.color || P.ink, style: o.style || 'rise', by: 'char', stagger: 0.05, dur: 0.6, align: o.align, tracking: o.tracking ?? -0.01, out: o.out, alpha: o.alpha, stroke: o.stroke, strokeW: o.strokeW });
  S6.lead = lead; S6.key = key; S6.mono = mono; S6.big = big;
