  S6.chip = (ctx, s, x, y, t, t0, o = {}) => {
    const k = prog(t, t0, t0 + 0.4); if (k <= 0) return; const sz = o.size || 24; const w = MG.text.width(ctx, s, { font: o.font || F.grotesk, weight: 700, size: sz, tracking: o.tracking ?? 0.06 }) + sz * 1.1; const h = sz * 1.55;
    const ax = o.align === 'right' ? 1 : o.align === 'left' ? 0 : 0.5; const x0 = x - w * ax, y0 = y - h / 2;
    ctx.save(); ctx.globalAlpha *= k * (o.alpha ?? 1); ctx.translate(0, (1 - k) * 10);
    const p = MG.path.rr(x0, y0, w * MG.ease.out(k), h, h / 2); MG.fx.shadow(ctx, p, { dx: 3, dy: 6, blur: 12, color: 'rgba(40,20,10,0.28)', fill: o.bg || P.cal }); ctx.fillStyle = o.bg || P.cal; ctx.fill(p);
    ctx.clip(p); MG.text.draw(ctx, s, x0 + sz * 0.55, y + sz * 0.36, { font: o.font || F.grotesk, weight: 700, size: sz, color: o.color || P.ink, tracking: o.tracking ?? 0.06 }); ctx.restore();
  };

  // ---------------------------------------------------------------- camera
