    if (!op.noTop) { ctx.strokeStyle = 'rgba(255,248,230,0.55)'; ctx.lineWidth = 1.4; ctx.beginPath(); ctx.moveTo(top[3][0], top[3][1]); ctx.lineTo(top[0][0], top[0][1]); ctx.lineTo(top[1][0], top[1][1]); ctx.stroke(); }
